"""Tests for tasks_api.models — Task, Tag, TaskStatus, TaskPriority."""

from __future__ import annotations

from datetime import datetime, timedelta, timezone

import pytest

from tasks_api.models import Tag, Task, TaskPriority, TaskStatus


class TestTag:
    def test_basic_creation(self):
        tag = Tag("Work")
        assert tag.name == "work"

    @pytest.mark.parametrize(
        "raw,expected",
        [
            ("  Python  ", "python"),
            ("UPPER", "upper"),
            ("with-hyphen", "with-hyphen"),
            ("under_score", "under_score"),
            ("abc123", "abc123"),
        ],
    )
    def test_normalization(self, raw, expected):
        assert Tag(raw).name == expected

    @pytest.mark.parametrize(
        "bad_name,error_type",
        [
            ("", ValueError),
            ("   ", ValueError),
            (123, TypeError),
            (None, TypeError),
            ("a" * 33, ValueError),
            ("has space", ValueError),
            ("has!bang", ValueError),
            ("dot.dot", ValueError),
        ],
    )
    def test_invalid_names(self, bad_name, error_type):
        with pytest.raises(error_type):
            Tag(bad_name)

    def test_max_length_boundary(self):
        tag = Tag("a" * 32)
        assert tag.name == "a" * 32


class TestTaskPriority:
    @pytest.mark.parametrize(
        "priority,expected_key",
        [
            (TaskPriority.HIGH, 0),
            (TaskPriority.MEDIUM, 1),
            (TaskPriority.LOW, 2),
        ],
    )
    def test_order_key(self, priority, expected_key):
        assert TaskPriority.order_key(priority) == expected_key


class TestTaskIsOverdue:
    def test_no_due_date(self):
        task = Task(id=1, title="t", created_at=datetime.now(timezone.utc))
        assert task.is_overdue(datetime.now(timezone.utc)) is False

    def test_done_task_not_overdue(self):
        past = datetime(2020, 1, 1, tzinfo=timezone.utc)
        task = Task(
            id=1, title="t", status=TaskStatus.DONE,
            due_at=past, created_at=datetime.now(timezone.utc),
        )
        assert task.is_overdue(datetime.now(timezone.utc)) is False

    def test_pending_past_due(self):
        past = datetime(2020, 1, 1, tzinfo=timezone.utc)
        now = datetime(2025, 6, 1, tzinfo=timezone.utc)
        task = Task(id=1, title="t", due_at=past, created_at=past)
        assert task.is_overdue(now) is True

    def test_pending_future_due(self):
        future = datetime(2099, 1, 1, tzinfo=timezone.utc)
        now = datetime(2025, 6, 1, tzinfo=timezone.utc)
        task = Task(id=1, title="t", due_at=future, created_at=now)
        assert task.is_overdue(now) is False

"""Tests for tasks_api.repository — InMemoryTaskRepository and normalize_tags."""

from __future__ import annotations

import pytest

from tasks_api.models import Tag, Task, TaskPriority, TaskStatus
from tasks_api.repository import InMemoryTaskRepository, normalize_tags
from tests.conftest import FIXED_NOW, make_task


class TestInMemoryTaskRepository:
    @pytest.fixture
    def repo(self):
        return InMemoryTaskRepository()

    def test_add_and_get(self, repo):
        task = make_task(id=1)
        repo.add(task)
        assert repo.get(1) is task

    def test_get_missing_returns_none(self, repo):
        assert repo.get(999) is None

    def test_add_duplicate_raises(self, repo):
        repo.add(make_task(id=1))
        with pytest.raises(ValueError, match="already exists"):
            repo.add(make_task(id=1))

    def test_list_returns_snapshot(self, repo):
        repo.add(make_task(id=1))
        repo.add(make_task(id=2, title="Second"))
        items = list(repo.list())
        assert len(items) == 2

    def test_update(self, repo):
        repo.add(make_task(id=1, title="Original"))
        updated = make_task(id=1, title="Updated")
        repo.update(updated)
        assert repo.get(1).title == "Updated"

    def test_update_missing_raises(self, repo):
        with pytest.raises(KeyError):
            repo.update(make_task(id=999))

    def test_delete_existing(self, repo):
        repo.add(make_task(id=1))
        assert repo.delete(1) is True
        assert repo.get(1) is None

    def test_delete_missing(self, repo):
        assert repo.delete(999) is False

    def test_next_id_increments(self, repo):
        assert repo.next_id() == 1
        assert repo.next_id() == 2
        assert repo.next_id() == 3

    def test_list_empty(self, repo):
        assert list(repo.list()) == []


class TestNormalizeTags:
    def test_strings_become_tags(self):
        result = normalize_tags(["Python", "flask"])
        assert [t.name for t in result] == ["python", "flask"]

    def test_deduplication(self):
        result = normalize_tags(["Python", "python", "PYTHON"])
        assert len(result) == 1
        assert result[0].name == "python"

    def test_mixed_tag_and_string(self):
        result = normalize_tags([Tag("api"), "API", "new"])
        assert [t.name for t in result] == ["api", "new"]

    def test_empty_input(self):
        assert normalize_tags([]) == []

    def test_preserves_first_seen_order(self):
        result = normalize_tags(["c", "a", "b", "a"])
        assert [t.name for t in result] == ["c", "a", "b"]
